function normText(v) {
  return String(v ?? '').trim().toLowerCase().replace(/[^a-z0-9]/g, '');
}
function normEmail(v) {
  return String(v ?? '').trim().toLowerCase();
}
function normPhone(v) {
  const d = String(v ?? '').replace(/\D/g, '');
  return d.length >= 10 ? d.slice(-10) : d;
}
function normCity(v) {
  const s = String(v ?? '').trim().toLowerCase();
  return ({'gurugram':'gurgaon','new delhi':'delhi','delhi ncr':'delhi',
            'bangalore':'bengaluru','bengaluru':'bengaluru'})[s] || s;
}

return $input.all().map(item => {
  const r = item.json || {};
  const name = r.name ?? r.Name ?? r['Full Name'] ?? r['worker_name'] ?? '';
  const email = r.email ?? r.Email ?? r.email_id ?? '';
  const phone = r.phone ?? r.Phone ?? r['Phone Number'] ?? '';
  const city = r.city ?? r.City ?? r.location ?? '';

  const ne = normEmail(email);
  const np = normPhone(phone);
  const nn = normText(name);
  const nc = normCity(city);

  const matches = master.filter(p =>
    (ne && p.email && ne === normEmail(p.email)) ||
    (np && p.phone && np === normPhone(p.phone)) ||
    (nn && nc && nn === normText(p.name) && nc === normCity(p.city))
  );

  return {
    json: {
      ...r,
      name, email, phone, city,
      duplicate: matches.length > 0,
      matched_person: matches[0] || null,
      match_type: matches.length ? (
        ne && matches.some(p => ne === normEmail(p.email)) ? 'email' :
        np && matches.some(p => np === normPhone(p.phone)) ? 'phone' : 'name+city'
      ) : 'none'
    }
  };
});
